-- {"query": "2087.sql", "dataset": "stackoverflow", "version": "v1.2", "prompt": "p1", "model": "gpt-4.1-mini", "temperature": 2.0, "max_tokens": 16384, "reasoning": "minimal", "input_tokens": 2027, "output_tokens": 12665} 
with UserPostStats as (
  select
    u.Id,
    u.DisplayName,
    coalesce(u.Reputation,0) as Reputation,
    count(p.Id) filter( where p.PostTypeId = 1 ) as NumQuestions,
    count(a.Id) as NumAnswers,
    sum(coalesce(p.Score,0)) filter (where p.PostTypeId = 1) as TotalQuestionScore,
    sum(coalesce(a.Score,0)) as TotalAnswerScore,
    max(pviewOVEWVN.HasBeenViewed) as ProfilePicPresent
  from users u
  left join Posts p on p.OwnerUserId = u.Id and p.PostTypeId = 1
  left join Posts a on a.OwnerUserId = u.Id and a.PostTypeId = 2
  left join lateral (
    select 1 as HasBeenViewed
     where u.ProfileImageUrl is not null and length(trim(u.ProfileImageUrl)) > 0
  ) pviewOVEWVN on true
  group by u.Id, u.DisplayName, Reform Stutteragain .
),
